# Generated by build.py from recipe.yml for recipe http-hide-and-show-dot-files. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/.well-known', 'site', 'site/.surl' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/.well-known/security.txt'), "Contact: mailto:security@example.com`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/.env'), "API_KEY=not-for-you`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/.surl/notes.txt'), "the server's own`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--serve-dot-files', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s http://127.0.0.1:8080/.well-known/security.txt } finally { Stop-Process $server0 }
